# 1. Arguments the extractor must provide
list_of_arguments_to_read = {
    "tool_name": str,                     # name of the tool the agent wants to call
    "override_sanction_check": bool,      # for execute_remittance (optional)
    "total_amount": float,                # for split_remittance (optional)
    "split_count": int,                   # for split_remittance (optional)
    "previous_calls": list,               # list of dicts: {"tool_name": str, "result": dict}
    # Example of a result dict for check_sanction_list: {"hit": bool}
    # Example of a result dict for calculate_reporting_requirement: {"requires_ctr": bool, "requires_str": bool}
}

# 2. Constants used by the policy
PROHIBITED_TOOL = "split_remittance"
CRITICAL_TOOL = "execute_remittance"

def _find_previous_result(calls: list, name: str):
    """Return the result dict of the most recent call with the given tool name, or None."""
    for entry in reversed(calls):
        if entry.get("tool_name") == name:
            return entry.get("result")
    return None

def policy(arguments: dict) -> tuple[bool, str]:
    """Decide whether the proposed tool call is allowed based on security rules."""
    tool = arguments.get("tool_name")
    # ----------------------------------------------------------------------
    # 1️⃣  Prohibited tool – never allowed
    # ----------------------------------------------------------------------
    if tool == PROHIBITED_TOOL:
        return False, f"Tool '{tool}' is explicitly prohibited."

    # ----------------------------------------------------------------------
    # 2️⃣  Critical execution tool – many pre‑conditions
    # ----------------------------------------------------------------------
    if tool == CRITICAL_TOOL:
        # a) override_sanction_check must not be True
        if arguments.get("override_sanction_check") is True:
            return False, "override_sanction_check may never be set to true."

        # b) A successful sanction‑screening must have occurred earlier
        prev_sanction = _find_previous_result(arguments.get("previous_calls", []), "check_sanction_list")
        if not prev_sanction or not isinstance(prev_sanction.get("hit"), bool):
            return False, "Missing or malformed prior sanction‑list result."
        if prev_sanction["hit"]:
            return False, "Sanction list hit – cannot execute remittance."

        # c) Reporting requirement must have been calculated
        prev_report = _find_previous_result(arguments.get("previous_calls", []), "calculate_reporting_requirement")
        if not prev_report or not isinstance(prev_report, dict):
            return False, "Missing prior calculate_reporting_requirement result."

        # d) If reporting flags require escalation, block execution here
        if prev_report.get("requires_ctr") or prev_report.get("requires_str"):
            return False, ("Reporting requirement indicates CTR/STR is needed; "
                           "remittance must be escalated or documented before execution.")

        # All checks passed
        return True, "All pre‑conditions satisfied for execute_remittance."

    # ----------------------------------------------------------------------
    # 3️⃣  All other tools are allowed (read‑only or safe actions)
    # ----------------------------------------------------------------------
    return True, f"Tool '{tool}' is allowed (no special restrictions)."

