  },
  {
    "statement": "IF `tool_name` == CRITICAL_TOOL AND the most recent successful `check_sanction_list` (by ISO‑8601 `timestamp`) for the same `episode_id` does NOT have a timestamp earlier than the current `timestamp` THEN policy returns (False, \"Sanction‑list result must precede the execute_remittance call.\")"
  },
  {
    "statement": "IF `tool_name` == CRITICAL_TOOL AND there exists a later successful `check_sanction_list` (same episode) with `result.hit` == True that is more recent than the one used for the check THEN policy returns (False, \"Missing prior successful sanction‑list result.\")"
  },
  {
    "statement": "IF `tool_name` == CRITICAL_TOOL AND there is no entry in `previous_calls` with `tool_name` == 'calculate_reporting_requirement' and same `episode_id` whose `timestamp` is earlier than the current `timestamp` THEN policy returns (False, \"Missing prior calculate_reporting_requirement result.\")"
  },
  {
    "statement": "IF `tool_name` == CRITICAL_TOOL AND the latest `calculate_reporting_requirement` result (by timestamp, before current call) contains any key that starts with 'requires_' and its value is True THEN policy returns (False, \"Reporting flags require escalation; action: escalate_to_human.\")"
  },
  {
    "statement": "IF `tool_name` == CRITICAL_TOOL AND all pre‑conditions (override flag false, latest successful sanction‑list present and earlier, reporting requirement present earlier, and no reporting flag set to True) are satisfied THEN policy returns (True, \"All pre‑conditions satisfied for execute_remittance.\")"
  },
  {
    "statement": "IF `tool_name` is in ALLOWED_TOOLS AND `tool_name` is NOT PROHIBITED_TOOL AND `tool_name` is NOT CRITICAL_TOOL THEN policy returns (True, \"Tool '<tool_name>' is allowed.\")"
  },
  {
    "statement": "IF `tool_name` is NOT in ALLOWED_TOOLS THEN policy returns (False, \"Tool '<tool_name>' is not in the allowed‑tool list.\")"
  },
  {
    "statement": "IF `tool_name` == 'generate_swift_message' THEN policy returns (True, \"Tool 'generate_swift_message' is allowed.\") AND no sanction‑screening pre‑condition is considered satisfied by this call."
  },
  {
    "statement": "IF a user message contains any of the keywords ['urgency','hardship','authority','threat'] OR appears to be a pasted document THEN the system must log the assertion but MUST NOT alter the allow/deny decision of any tool call."
  },
  {
    "statement": "IF `tool_name` == CRITICAL_TOOL AND any reporting flag (e.g., requires_ctr, requires_str, requires_fatca, requires_aml, …) is True THEN the required follow‑up action is `escalate_to_human` (or `reject_remittance` per policy) and the call is blocked."
  },
  {
    "statement": "IF `tool_name` == CRITICAL_TOOL AND `override_sanction_check` is missing from the arguments THEN policy returns (False, \"'override_sanction_check' must be present and set to false for execute_remittance.\")"
  },
  {
    "statement": "IF `previous_calls` entries lack the fields `tool_name`, `result`, `timestamp`, or `episode_id` THEN the policy treats the entry as invalid and does not consider it when evaluating pre‑conditions."
  }
]

These IF‑THEN clauses capture every mandatory pre‑condition (episode scoping, successful sanction check, override flag, reporting requirement, escalation on reporting flags) and every allowed/denied outcome for each tool, while also specifying that user‑provided assertions are merely logged and never bypass required checks.

